def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        return 'C'

    opp_retaliated = False
    for i in range(1, n):
        if history[i-1][0] == 'D' and history[i][1] == 'D':
            opp_retaliated = True
            break

    if not opp_retaliated:
        return 'D'

    last_me, last_opp = history[-1]

    if last_opp == 'D':
        streak_d = 0
        for i in range(n-1, -1, -1):
            if history[i][1] == 'D':
                streak_d += 1
            else:
                break
        if last_me == 'D' and streak_d >= 3:
            return 'C'
        total_opp_D = sum(1 for _, o in history if o == 'D')
        if last_me == 'C' and total_opp_D <= 2:
            return 'C'
        return 'D'
    else:
        if last_me == 'D':
            return 'C'
        return 'C'
